css:
.tpl-magazine {
  box-sizing: border-box; width: 100%; height: 100%; min-width: 0; min-height: 0;
  display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; gap: 1em;
  padding: clamp(12px, 3.5vw, 24px); color: var(--reader-text-color, inherit);
  background: var(--reader-page-background, transparent);
}
.tpl-magazine__columns { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 1.15em; min-width: 0; min-height: 0; }
.tpl-magazine__column { min-width: 0; min-height: 0; }
.tpl-magazine__column + .tpl-magazine__column { border-left: 1px solid currentColor; padding-left: 1.15em; }
.tpl-magazine__meta { display: flex; min-width: 0; justify-content: space-between; align-items: center; gap: 1em; font-size: .6em; line-height: 1.4; opacity: .7; }
.tpl-magazine__meta > * { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tpl-magazine__opening { min-width: 0; border-top: 4px solid var(--reader-accent, currentColor); padding-top: .6em; }
.tpl-magazine__feature { position: relative; min-width: 0; overflow: hidden; padding: .85em 0 .1em; }
.tpl-magazine__eyebrow { position: relative; display: flex; align-items: center; justify-content: space-between; font-size: .58em; line-height: 1.25; letter-spacing: .22em; color: var(--reader-accent, currentColor); }
.tpl-magazine__seal { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; width: 2em; height: 2em; border: 1px solid currentColor; letter-spacing: 0; transform: rotate(-8deg); margin: .15em .2em; }
.tpl-magazine__art { position: absolute; right: -.4em; top: .45em; width: 7em; height: 7em; max-width: 42%; max-height: 100%; color: var(--reader-accent, currentColor); opacity: .09; }
.tpl-magazine__opening h1 { position: relative; margin: .4em 0 .5em; font-size: 1.75em; font-size: clamp(22px, 7vw, 1.85em); line-height: 1.28; letter-spacing: -.015em; font-weight: 700; overflow-wrap: anywhere; word-break: break-word; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden; }
.tpl-magazine__signature { display: flex; align-items: center; gap: .45em; height: .35em; color: var(--reader-accent, currentColor); }
.tpl-magazine__signature span:first-child { width: 2.6em; border-top: 3px solid currentColor; }
.tpl-magazine__signature span:last-child { flex: 1; border-top: 1px solid currentColor; opacity: .3; }
.tpl-magazine__signature i { width: .22em; height: .22em; background: currentColor; transform: rotate(45deg); }
.tpl-magazine [data-reader-decoration] { pointer-events: none; user-select: none; }
.tpl-magazine__running { border-bottom: 1px solid currentColor; padding-bottom: .65em; }
.tpl-magazine footer { border-top: 1px solid currentColor; padding-top: .65em; }
.tpl-magazine .reader-chapter-title { display: none; }
.tpl-magazine .reader-paragraph { text-align: justify; }
[data-reader-page="first"] .tpl-magazine { gap: 1.1em; }
@media (max-height: 480px) {
  .tpl-magazine, [data-reader-page="first"] .tpl-magazine { gap: 8px; padding-top: 10px; padding-bottom: 10px; }
  .tpl-magazine__meta { font-size: .6em; font-size: min(.6em, 12px); }
  .tpl-magazine__opening { padding-top: 6px; border-top-width: 2px; }
  .tpl-magazine__feature { padding-top: 6px; }
  .tpl-magazine__eyebrow { font-size: 10px; }
  .tpl-magazine__seal { display: none; }
  .tpl-magazine__opening h1 { margin: 6px 0 8px; font-size: 24px; font-size: clamp(18px, 4vw, 24px); -webkit-line-clamp: 2; }
  .tpl-magazine__signature { height: 5px; gap: 8px; }
  .tpl-magazine__art { width: 88px; height: 88px; top: 0; }
}
@media (max-height: 360px) {
  .tpl-magazine__eyebrow, .tpl-magazine__art { display: none; }
  .tpl-magazine__opening h1 { -webkit-line-clamp: 1; }
}
